function getApplicableRules(profileIds, intent) {
  return RULES_REGISTRY.filter((rule) => {
    try {
      return rule.applies_when(profileIds, intent);
    } catch (e) {
      return false;
    }
  });
}





const SENSITIVE_CONFIDENCE_CAP = 0.55;

/**
 * Deterministic keyword-heuristic classifier. NOT an AI/ML classifier — this is
 * explicit and tested, never silently presented as AI-driven inference.
 *
 * Returns an array of { profile_id, confidence, reason, evidence, source } —
 * source is ALWAYS 'INFERRED_DEFAULT', per the governing invariant
 * INFERRED != USER_REQUIREMENT. The caller (UI) must let the user edit/reject
 * before generation (section 7).
 *
 * v2 (gap-closing batch): adds negative-keyword suppression and a confidence
 * cap for `sensitive` profiles (FINANCIAL_SYSTEM, LEGAL_SYSTEM) — this is the
 * real fix for the previously-documented false positive where "فواتير" inside
 * a clinic/booking context used to wrongly trigger FINANCIAL_SYSTEM. Also adds
 * a specificity tie-break so a more specific profile (e.g. MULTI_TENANT_SAAS,
 * PUBLIC_PORTAL) outranks a more generic one (WEB_SAAS, WEB_APPLICATION) when
 * both match overlapping text with otherwise-equal confidence.
 */
function classifyProject(intent) {
  const haystack = ((intent.project_name || '') + ' ' + (intent.project_goal || '') + ' ' +
    ((intent.advanced && intent.advanced.special_constraints) || ''))
    .toLowerCase();

  const matches = [];
  for (const profile of PROFILE_REGISTRY) {
    const kws = profile.triggers.keywords || [];
    const negKws = (profile.triggers && profile.triggers.negative_keywords) || [];
    const evidence = kws.filter((kw) => haystack.includes(kw.toLowerCase()));
    if (evidence.length === 0) continue;

    const negHits = negKws.filter((nk) => haystack.includes(nk.toLowerCase()));
    if (profile.triggers.sensitive && negHits.length > 0 && evidence.length <= negHits.length) {
      // Negative-signal suppression: a sensitive profile with weak/ambiguous
      // evidence outweighed by contextual negative signals is not reported at all.
      continue;
    }

    let confidence = Math.min(0.9, 0.5 + evidence.length * 0.15);
    if (profile.triggers.sensitive && evidence.length === 1) {
      confidence = Math.min(confidence, SENSITIVE_CONFIDENCE_CAP);
    }

    matches.push({
      profile_id: profile.id,
      confidence: Math.round(confidence * 100) / 100,
      reason: 'عُثر على الكلمات المفتاحية: ' + evidence.join('، '),
      evidence,
      source: 'INFERRED_DEFAULT',
    });
  }

  // Explicit advanced-input overrides (still INFERRED_DEFAULT, not CONFIRMED, because
  // the profile itself is our interpretation even when the signal is a direct field).
  if (intent.advanced && intent.advanced.multi_tenancy === 'yes') {
    const existing = matches.find((m) => m.profile_id === 'MULTI_TENANT_SAAS');
    if (existing) {
      existing.confidence = Math.max(existing.confidence, 0.85);
    } else {
      matches.push({
        profile_id: 'MULTI_TENANT_SAAS',
        confidence: 0.85,
        reason: 'الحقل المتقدم "تعدد المستأجرين" = نعم',
        evidence: [],
        source: 'INFERRED_DEFAULT',
      });
    }
  }

  function maxEvidenceLength(m) {
    return m.evidence.reduce((max, kw) => Math.max(max, kw.length), 0);
  }
  matches.sort((a, b) => {
    if (b.confidence !== a.confidence) return b.confidence - a.confidence;
    return maxEvidenceLength(b) - maxEvidenceLength(a);
  });

  if (matches.length === 0) {
    return [
      {
        profile_id: 'WEB_APPLICATION',
        confidence: 0.3,
        reason: 'لم يُعثر على كلمات مفتاحية واضحة — تصنيف افتراضي عام منخفض الثقة، يُنصح بالمراجعة اليدوية',
        evidence: [],
        source: 'INFERRED_DEFAULT',
      },
    ];
  }

  return matches;
}





/**
 * Classifies every rule in the registry (not just applicable ones) into
 * REQUIRED / OPTIONAL / NOT_APPLICABLE_WITH_RATIONALE for full transparency —
 * a non-applicable rule is an explicit decision, not a silent omission.
 */

function computeApplicability(profileIds, intent) {
  const applicableIds = new Set(getApplicableRules(profileIds, intent).map((r) => r.id));
  return RULES_REGISTRY.map((rule) => {
    if (applicableIds.has(rule.id)) {
      return { id: rule.id, domain: rule.domain, description: rule.description, status: rule.severity };
    }
    return {
      id: rule.id,
      domain: rule.domain,
      description: rule.description,
      status: 'NOT_APPLICABLE_WITH_RATIONALE',
      rationale: 'لا ينطبق على مزيج الـProfiles الحالي (' + profileIds.join(', ') + ')',
    };
  });
}




/**
 * Suggests an architecture pattern per profile composition, using a generic
 * 5-pattern reference (Layered, Clean/Hexagonal, Event-Driven, Microservices,
 * Modular Monolith) and the "ابدأ بالبسيط" (start simple unless proven
 * otherwise) principle. Always tagged INFERRED_DEFAULT — never presented as
 * a firm decision.
 */
function suggestArchitecture(profileIds) {
  if (profileIds.indexOf('MULTI_TENANT_SAAS') !== -1 || profileIds.indexOf('FINANCIAL_SYSTEM') !== -1) {
    return {
      pattern: 'Clean / Hexagonal (مبسّطة)',
      reason: 'عزل منطق الأعمال عن قاعدة البيانات والواجهة ضروري هنا لحماية قواعد العزل/التدقيق من تقلبات البنية التحتية لاحقًا.',
      source: 'INFERRED_DEFAULT',
    };
  }
  if (profileIds.indexOf('API_SERVICE') !== -1 && profileIds.length === 1) {
    return {
      pattern: 'Layered (طبقية بسيطة)',
      reason: 'خدمة API مفردة بلا تعقيد تعدد مستأجرين أو حساسية مالية — الطبقية البسيطة كافية؛ لا داعٍ لتعقيد إضافي الآن.',
      source: 'INFERRED_DEFAULT',
    };
  }
  return {
    pattern: 'Layered (طبقية بسيطة)',
    reason: 'النمط الافتراضي الأبسط — طبّق "ابدأ بالبسيط": لا يوجد مؤشر حالي (حجم، تعقيد مالي، تعدد مستأجرين) يبرر معمارية أعقد.',
    source: 'INFERRED_DEFAULT',
  };
}




/**
 * Generic lifecycle journey + per-profile customization. Proves real
 * differentiation (section 15/36), not just name/description substitution.
 */
const GENERIC_JOURNEY = ['Discover', 'Input/Create', 'Validate', 'Persist', 'Retrieve', 'Edit', 'Process', 'Complete/Cancel', 'Notify', 'Audit'];

const PROFILE_JOURNEYS = {
  ECOMMERCE: ['تصفّح المنتجات', 'إضافة للسلة', 'الدفع (Checkout)', 'تأكيد الطلب', 'تتبع الشحن'],
  BOOKING_SYSTEM: ['اختيار الموعد المتاح', 'تأكيد الحجز', 'إرسال تذكير', 'الحضور أو الإلغاء', 'تقييم بعد الخدمة (اختياري)'],
  AI_ASSISTANT: ['طرح السؤال', 'استرجاع السياق', 'توليد إجابة مع درجة ثقة', 'عرض المصادر إن وُجدت', 'تصعيد لمراجعة بشرية عند الشك'],
  FINANCIAL_SYSTEM: ['إدخال المعاملة', 'تحقق مزدوج', 'ترحيل للسجل غير القابل للتعديل', 'مطابقة/تسوية', 'تقرير مالي'],
  GIS_SYSTEM: ['تحديد نطاق الدراسة', 'استعلام مكاني', 'عرض الطبقات', 'تحليل التداخل/القرب', 'تصدير الخريطة'],
  API_SERVICE: ['استقبال الطلب', 'تحقق من صحة المدخلات', 'تنفيذ المنطق', 'إرجاع استجابة موحّدة الشكل', 'تسجيل الحدث'],
};

function compileJourneys(profileIds) {
  const journeys = [{ name: 'الدورة العامة (Generic Lifecycle)', steps: GENERIC_JOURNEY, source: 'INFERRED_DEFAULT' }];
  profileIds.forEach((id) => {
    if (PROFILE_JOURNEYS[id]) {
      journeys.push({ name: 'رحلة مخصصة: ' + id, steps: PROFILE_JOURNEYS[id], source: 'INFERRED_DEFAULT' });
    }
  });
  return journeys;
}



/**
 * brownfieldEngine.js — text-based (NOT code-inspection-based) gap
 * assessment for an existing project. Compares the user's own free-text
 * description of existing_capabilities against the computed required
 * rules. Honestly documented: this produces ASSUMED, not CONFIRMED,
 * preserve/add lists, because no real source code is inspected here.
 */
function assessBrownfield(intent, requiredRules) {
  const adv = intent.advanced || {};
  if (!adv.existing_project) return null;

  const existingText = (adv.existing_capabilities || '').toLowerCase();
  const preserve = [];
  const add = [];

  requiredRules.forEach((rule) => {
    const descWords = rule.description.toLowerCase();
    const mentioned = existingText.length > 0 && (
      existingText.indexOf(rule.id.toLowerCase()) !== -1 ||
      descWords.split(' ').some((w) => w.length > 4 && existingText.indexOf(w) !== -1)
    );
    if (mentioned) {
      preserve.push({ rule_id: rule.id, note: 'المستخدم ذكر ما يشبه هذا ضمن existing_capabilities (ASSUMED، غير مؤكد من كود حقيقي)' });
    } else {
      add.push({ rule_id: rule.id, note: 'لم يُذكر في existing_capabilities؛ يُفترض أنه فجوة (ASSUMED)' });
    }
  });

  return {
    mode: 'EXISTING_PROJECT',
    current_reality: {
      existing_repository: adv.existing_repository || null,
      existing_architecture: adv.existing_architecture || null,
      existing_stack: adv.existing_stack || [],
      existing_tests: adv.existing_tests || null,
      known_gaps_stated_by_user: adv.known_gaps || null
    },
    gap_assessment: {
      preserve,
      add,
      refine: [], // honestly empty: no real code inspection available
      remove_only_with_reason: [] // honestly empty: same reason
    },
    note: 'هذا تقييم نصي (Text-based) يعتمد كليًا على وصف المستخدم لما هو موجود حاليًا (existing_capabilities)، وليس فحصًا فعليًا للكود المصدري. قوائم preserve/add هي ASSUMED لا CONFIRMED. refine وremove_only_with_reason تُركا خاليين عمدًا لعدم توفر فحص كود حقيقي في هذه البيئة.'
  };
}




